'use strict';
window.ProcessingUI=(()=>{
 const d=window.HERB_DATA,p=window.PROCESSING_DATA,M=window.ProcessingModel;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=x=>Number.isFinite(x)?new Intl.NumberFormat('zh-TW',{maximumFractionDigits:2}).format(x):'未錄';
 const H=id=>d.herbs.find(h=>h.id===id),profile=id=>p.profiles.find(x=>x.id===id);
 const link=(url,label)=>/^https:\/\//.test(url||'')?`<a class="small-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
 let ctx,editingId=null;
 function get(){return M.resolveSelection(ctx.selection(),d,p,{basis:ctx.basis()})}
 function options(row){return `<option value="source_unspecified" ${(row.processingId||'source_unspecified')==='source_unspecified'?'selected':''}>沿用原條目・炮製未選</option>${p.profiles.filter(x=>x.herbIds?.includes(row.id)).map(x=>`<option value="${esc(x.id)}" ${row.processingId===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}<option value="custom_unverified" ${row.processingId==='custom_unverified'?'selected':''}>自訂工藝・藥性未核</option>`}
 function selectedAttributes(row){const result=M.resolveSelection([row],d,p,{basis:'research'});return result.derivedData.herbs.find(h=>h.id===row.id)}
 function recordCard(row){const h=H(row.id),effective=selectedAttributes(row),pr=profile(row.processingId);return `<article class="material-record"><div class="material-record-heading"><div><button class="material-name" data-detail="${esc(row.id)}">${esc(h.name)}</button>${h.toxic?'<span class="risk-mini">慎</span>':''}<span class="material-attributes">${esc(effective?.nature||'炮製後性未錄')} · ${esc(effective?.flavors?.join('、')||'味未錄')}</span></div><button class="remove" data-remove="${esc(row.id)}" aria-label="移除${esc(h.name)}">×</button></div><div class="material-controls"><label class="processing-choice">炮製方式<select data-processing="${esc(row.id)}" aria-label="${esc(h.name)}炮製方式">${options(row)}</select></label><label>實錄質量（g）<input class="grams-input" type="number" min="0.01" step="0.01" inputmode="decimal" value="${row.grams??''}" placeholder="未錄" data-grams="${esc(row.id)}" aria-label="${esc(h.name)}克數"></label><label>研究份數<div class="ratio-control"><button data-step="-1" data-id="${esc(row.id)}" aria-label="減少${esc(h.name)}研究份數" ${row.ratio<=1?'disabled':''}>−</button><input type="number" min="1" max="20" step="1" value="${row.ratio}" data-ratio="${esc(row.id)}" aria-label="${esc(h.name)}研究份數"><button data-step="1" data-id="${esc(row.id)}" aria-label="增加${esc(h.name)}研究份數" ${row.ratio>=20?'disabled':''}>+</button></div></label><label>結構標註<select class="role-select" data-role="${esc(row.id)}" aria-label="${esc(h.name)}結構標註">${['未標註','君','臣','佐','使'].map(r=>`<option ${row.role===r?'selected':''}>${r}</option>`).join('')}</select></label></div><div class="material-record-foot"><span>${row.sourceProcessingNote?`原方註記：${esc(row.sourceProcessingNote)}`:'原方炮製註記未載入；未載不表示生品'}${pr?` · ${esc(pr.workflow?.map(s=>s.label).join(' · ')||'工藝步驟待核')}`:''}</span><button class="text-button" data-process-record="${esc(row.id)}">工藝流程與實錄</button></div>${row.processingId&&row.processingId!=='source_unspecified'?`<div class="processing-effect-note">${effectSummary(row,effective)}</div>`:''}</article>`}
 function effectSummary(row,effective){const h=H(row.id),pr=profile(row.processingId);if(row.processingId==='custom_unverified')return '自訂工藝僅保存實錄；炮製後性味與功用保留未知。';return `原條目：${esc(h.nature||'性未錄')} → 所選分支：${esc(effective?.nature||'性未錄')}。${effective?.effects?.length?'功用原詞：'+effective.effects.map(esc).join('、')+'。':'此分支功用未錄。'} <span class="table-note">依文獻分支；非藥效增減倍率</span>`}
 function summaryHTML(){const r=get();if(!ctx.selection().length)return `<div><b>未加入材料</b><span>尚無全方實錄質量</span></div><p>加入材料後，可分別記錄克數與稱量階段。</p>`;return `<div><b>${fmt(r.knownGrams)} g</b><span>${r.missingGrams.length?'已錄子集質量':'全方實錄質量'} · ${ctx.selection().length-r.missingGrams.length} / ${ctx.selection().length} 味已錄</span></div><p>${r.missingGrams.length?`未錄克數：${r.missingGrams.map(id=>esc(H(typeof id==='string'?id:id.id)?.name||id.name||id)).join('、')}。`:'克數已完整記錄。'}原方古籍單位保留原文，未換算成克數。</p>`}
 function updateSummary(){const el=document.querySelector('#mass-summary');if(el)el.innerHTML=summaryHTML()}
 function renderSelection(context){ctx=context;const rows=ctx.selection(),mass=ctx.massContext();document.querySelector('#formula-panel').innerHTML=`<div class="formula-head"><div><div class="formula-label">當前配伍 · ${rows.length} 味</div><input class="formula-name" id="formula-name" maxlength="60" value="${esc(ctx.name())}" aria-label="研究名稱"></div><select class="template-select" id="template" aria-label="載入經典方劑"><option value="">載入經典方劑</option>${d.formulas.map(f=>`<option value="${esc(f.id)}" ${ctx.loadedFormulaId()===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><div class="material-records">${rows.length?rows.map(recordCard).join(''):'<div class="empty-state">從本草藥櫃加入材料，或載入經典方劑。</div>'}</div><div class="mass-settings"><div class="weight-basis-controls"><label>標籤分布依據<select id="weight-basis" aria-label="標籤分布計量依據"><option value="research" ${ctx.basis()==='research'?'selected':''}>研究份數</option><option value="grams" ${ctx.basis()==='grams'?'selected':''}>實錄克數（g）</option></select></label><label>稱量階段<select id="mass-stage" aria-label="克數稱量階段">${[['unrecorded','稱量階段未錄'],['processed_dry','炮製後乾飲片・煎煮投入前'],['raw_dry','炮製前乾原料'],['other','其他實測材料・見來源記錄']].map(([v,label])=>`<option value="${v}" ${mass.stage===v?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="mass-record-fields"><label>研究批次<input id="mass-batch" maxlength="80" placeholder="可記錄批次" value="${esc(mass.batch)}" aria-label="質量記錄批次"></label><label>克數記錄來源<input id="mass-source" maxlength="160" placeholder="例如：稱量記錄或實驗編號" value="${esc(mass.source)}" aria-label="克數記錄來源"></label></div><div id="mass-summary" class="mass-summary">${summaryHTML()}</div><p class="rule-note">克數由研究者填寫，不預填服用量；全部材料記錄完整後才按質量計分布。圖表表示文獻標籤的質量占比，未建立劑量與藥效關係。君臣佐使為研究者標註。</p></div><div class="formula-bottom"><p>${p.profiles.length} 個來源炮製分支<br>工藝實錄可保存溫度、時間、媒介與批次。</p><button class="button primary" id="analyze" ${!rows.length?'disabled':''}>模擬配伍</button></div>`}
 function evidenceHTML(pr){if(!pr)return '<p class="rule-note">尚無所選工藝的典籍屬性證據；研究者的溫度、時間或媒介實錄不自動轉成藥性變化。</p>';return (pr.sourceQuotes||[]).map(q=>{const sid=q.sourceId||pr.sourceId,s=(p.sources||[]).find(s=>s.id===sid)||d.sources.find(s=>s.id===sid);const ev=q.evidenceSpan||q;return `<div class="record-evidence"><blockquote class="source-quote">${esc(q.text||q.quote||ev.text||'')}</blockquote>${s?link(s.url,s.title):''}${Number.isInteger(ev.start)?`<p class="table-note">Unicode 字符 ${ev.start}–${ev.end} · ${esc(ev.basis||'')}</p>`:''}</div>`}).join('')+`<p class="rule-note">${(pr.limitations||[]).map(esc).join('；')}</p>`}
 function workflowHTML(pr){return pr?.workflow?.length?`<ol class="process-flow">${pr.workflow.map(step=>`<li><strong>${esc(step.label)}</strong><p>${esc(step.note||'')}</p>${step.sourceId?`<small>來源：${esc((p.sources||[]).find(s=>s.id===step.sourceId)?.title||step.sourceId)}</small>`:''}</li>`).join('')}</ol><p class="rule-note">以上是典籍所載步驟。未載的溫度、時間、輔料比例與品質終點保留未知，完整操作條件仍待核。</p>`:'<p class="rule-note">未選來源工藝，或來源不足以還原完整流程。可在下方記錄實際工藝。</p>'}
 function openRecord(id){const row=ctx.selection().find(s=>s.id===id);if(!row)return;editingId=id;const h=H(id),r=row.processRecord||{};document.querySelector('#processing-detail').innerHTML=`<div class="eyebrow">PROCESSING RECORD</div><h2>${esc(h.name)} · 工藝流程</h2><p class="table-note">原方註記：${esc(row.sourceProcessingNote||'未載入；未錄不代表生品')}</p><label class="process-profile-label">研究選擇<select id="record-processing" aria-label="工藝記錄炮製方式">${options(row)}</select></label><div id="process-source-flow">${workflowHTML(profile(row.processingId))}</div><details><summary>查看屬性與工藝的原文依據</summary><div id="process-source-evidence">${evidenceHTML(profile(row.processingId))}</div></details><h3>研究者實錄</h3><p class="rule-note">記錄實際工藝；溫度及時間沒有預設標準，未錄參數保留未知。</p><div class="process-record-grid"><label>本味批次<input id="record-batch" maxlength="80" value="${esc(r.batch)}" aria-label="工藝批次"></label><label>設備<input id="record-equipment" maxlength="100" value="${esc(r.equipment)}" aria-label="工藝設備"></label><label>實錄溫度（°C）<input id="record-temperature" type="number" step="0.1" value="${r.temperatureC??''}" placeholder="未錄" aria-label="工藝溫度"></label><label>實錄時間（分鐘）<input id="record-duration" type="number" min="0" step="0.1" value="${r.durationMinutes??''}" placeholder="未錄" aria-label="工藝時間"></label><label class="wide-field">輔料／媒介<input id="record-medium" maxlength="120" value="${esc(r.medium)}" placeholder="未錄" aria-label="工藝輔料或媒介"></label><label class="wide-field">步驟與參數備註<textarea id="record-notes" maxlength="4000" rows="4" placeholder="可按實際順序記錄清理、切製、浸潤、加熱、乾燥等步驟" aria-label="實錄工藝步驟">${esc(r.stepsNote)}</textarea></label></div><div class="process-dialog-actions"><button class="button secondary" id="cancel-process-record">取消</button><button class="button primary" id="save-process-record">儲存工藝實錄</button></div>`;document.querySelector('#processing-dialog').showModal()}
 function numberField(id){const el=document.querySelector(id);if(el.value==='')return null;const value=Number(el.value);if(!Number.isFinite(value)||!el.checkValidity())throw new Error('請核對溫度與時間數值');return value}
 function saveRecord(){try{const value=id=>document.querySelector(id).value;const record={batch:value('#record-batch'),equipment:value('#record-equipment'),temperatureC:numberField('#record-temperature'),durationMinutes:numberField('#record-duration'),medium:value('#record-medium'),stepsNote:value('#record-notes')};if(!ctx.updateRow(editingId,{processingId:value('#record-processing'),processRecord:record},true))return;document.querySelector('#processing-dialog').close();ctx.notify('已儲存工藝實錄；藥性只採用有原文依據的分支')}catch(error){ctx.notify(error.message)}}
 function validateInputs(){for(const el of document.querySelectorAll('[data-grams]')){if(!el.checkValidity()){el.reportValidity();ctx.notify('克數請填正數，或留空表示未錄');return false}}return true}
 document.addEventListener('input',e=>{if(e.target.dataset.grams){const raw=e.target.value,value=raw===''?null:Number(raw);if((value===null||Number.isFinite(value)&&value>0)&&e.target.checkValidity()){ctx.updateRow(e.target.dataset.grams,{grams:value},false);updateSummary()}else{ctx.updateRow(e.target.dataset.grams,{grams:null},false);updateSummary()}}if(e.target.id==='mass-batch'||e.target.id==='mass-source')ctx.setMassContext({[e.target.id==='mass-batch'?'batch':'source']:e.target.value})});
 document.addEventListener('change',e=>{if(e.target.dataset.processing)ctx.updateRow(e.target.dataset.processing,{processingId:e.target.value},true);if(e.target.id==='weight-basis')ctx.setBasis(e.target.value);if(e.target.id==='mass-stage')ctx.setMassContext({stage:e.target.value});if(e.target.id==='record-processing'){document.querySelector('#process-source-flow').innerHTML=workflowHTML(profile(e.target.value));document.querySelector('#process-source-evidence').innerHTML=evidenceHTML(profile(e.target.value))}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.processRecord)openRecord(b.dataset.processRecord);if(b.id==='save-process-record')saveRecord();if(b.id==='cancel-process-record'||b.id==='close-processing')document.querySelector('#processing-dialog').close()});
 return {bindContext:context=>{ctx=context},renderSelection,validateInputs,updateSummary,fmt};
})();
